query:
-- Get the car ID first
SET @carId = (SELECT id FROM cars 
  WHERE make = 'KIA' AND model = 'EV6' AND year = 2023 
    AND price = 29995
    AND dealerId IN (SELECT id FROM dealers WHERE name LIKE '%EMG%')
  LIMIT 1);

-- Delete from dealer watchlist
DELETE FROM dealerWatchlist WHERE carId = @carId;

-- Delete from dealer cart
DELETE FROM dealerCart WHERE carId = @carId;

-- Delete related bids
DELETE FROM dealerBids WHERE carId = @carId;

-- Delete related finance applications
DELETE FROM financeApplications WHERE carId = @carId;

-- Now delete the car
DELETE FROM cars WHERE id = @carId;

SELECT CONCAT('Car ID ', @carId, ' (KIA EV6 from EMG) deleted successfully') as result;

